/*
B_i = A_i
        where
        A_i: ℝ ^ (2 × 2): a matrix
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    std::vector<Eigen::Matrix<DT, 2, 2>> B;

    heartlib(const std::vector<Eigen::Matrix<double, 2, 2>> & A)
    {
        const long dim_0 = A.size();
        // B_i = A_i
        B.resize(dim_0);
        for( int i=1; i<=dim_0; i++){
            B.at(i-1) = A.at(i-1);
        }
    }
};

