function output = heartlib(A)
% output = heartlib(A)
%
%    B_i = A_i
%            where
%            A_i: ℝ ^ (2 × 2): a matrix
    dim_0 = size(A, 1);
    assert( isequal(size(A), [dim_0, 2, 2]) );

    % B_i = A_i

    B = zeros(dim_0, 2, 2);
    for i = 1:dim_0
        squeeze(B(i,:,:)) = squeeze(A(i,:,:));
    end
    output.B = B;
end

